#!/usr/bin/env python3
"""Explicit CPU-to-A40 handoff of untouched five-arm groups.

WSL --run configures an experiment-specific forced-command SSH key (never your
personal private key), reserves the first untouched CPU group with mkdir, and
starts a Cherry transfer coordinator. The current CPU group finishes unchanged;
the old worker's existing no-overwrite guard stops it at the reservation.
A40 generations are archived on Cherry before the next GPU group can start.
A separate network-isolated Cherry worker evaluates those exact saved sources.
No driver/model/runtime installation; no old candidate regenerated or remeasured.
"""
from __future__ import annotations
import argparse,base64,contextlib,fcntl,gzip,hashlib,http.client,io,json,os,re,shlex
import shutil,signal,socket,stat,subprocess,sys,tarfile,tempfile,time,traceback,types,unittest,uuid
from pathlib import Path
from collections import Counter
from unittest import mock
sys.dont_write_bytecode=True
C_SHA='42b121e29737af1437daadad7a244d612ca156590f58d57d76c3fb036078c3fc'
C_GZ=''
A_SHA='36e0a03e88e0bec67dac1286803a0201299deda333bb740a0b8acf485bebd01a'
A_GZ=''
def embedded(name,blob,pin):
    raw=gzip.decompress(base64.b64decode(blob,validate=True))
    if hashlib.sha256(raw).hexdigest()!=pin:raise RuntimeError('Embedded source mismatch')
    mod=types.ModuleType(name);mod.__file__='<pinned-'+name+'>';sys.modules[name]=mod
    exec(compile(raw,mod.__file__,'exec'),mod.__dict__);return mod
C=embedded('handoff_continuation',C_GZ,C_SHA)
A=embedded('handoff_a40_setup',A_GZ,A_SHA)
P,R=C.P,C.R
read,save,jw,atomic,parse,canon,sha,hfile,need,checked,rel=P.read,P.save,P.jw,P.atomic,P.parse,P.canon,P.sha,P.hfile,P.need,P.checked,P.rel
Blocked=P.Blocked
now=P.now
VERSION='a40-handoff-1.0.0'
RPC_FIX='json-stdout-1'
PREDECESSOR_SHA='f8a613b015d146c068e7a0cfeec202a6a8951a2bfabbb45e17ebc511eb59c4da'
CPU_ROOT=Path('/srv/research/cpucond-open14b-continuous-v1')
CPU_UNIT='cpucond69-open14b-continuous-v1.service'
CH=Path('/srv/research/cpucond-a40-handoff-v1')
GP=Path('/workspace/cpucond-a40-handoff-v1')
PREP=Path('/workspace/cpucond-runpod-a40-prepare-v3')
BRIDGE_UNIT='a40-handoff-bridge-v1.service'
EVAL_UNIT='cpucond69-a40-handoff-eval-v1.service'
LOCK='/run/lock/cpucond-a40-handoff-control-v1.lock'
LOCAL_REL='workspace/cpu-conditioned-llm-optimization/runs/a40-handoff-v1'
GPU_UUID='GPU-00000000-0000-0000-0000-000000000000'
GPU_PORT=11529
MAX_TRANSFER=512*1024**2
LIVE={'active','activating','deactivating','reloading'}
GROUP_RE=re.compile(r'group-\d{3}')
GPU_STRATUM='CUDA_A40_b10964_Q4_K_M'
CPU_STRATUM='CPU_Skylake_b10964_Q4_K_M'

def at(root,unit=EVAL_UNIT):
    C.ROOT=root;C.UNIT=unit;C.configure();C.NATIVE=None

def sync_dir(path):
    fd=os.open(path,os.O_RDONLY|os.O_DIRECTORY)
    try:os.fsync(fd)
    finally:os.close(fd)

def once(path,raw):
    checked(path)
    if path.exists():need(read(path)==raw,'Immutable file conflict: '+str(path))
    else:save(path,raw)

def lock(path):
    stack=contextlib.ExitStack()
    try:
        fd=os.open(checked(path),os.O_CREAT|os.O_RDWR|os.O_NOFOLLOW,0o600)
        f=stack.enter_context(os.fdopen(fd,'a'));fcntl.flock(f,fcntl.LOCK_EX|fcntl.LOCK_NB)
        return stack
    except BaseException:stack.close();raise

def state(unit):
    if unit!=BRIDGE_UNIT:return R.state(unit)
    cp=subprocess.run(['systemctl','show',unit,'-p','LoadState','-p','ActiveState','-p','SubState','-p','MainPID','-p','Result','-p','ExecMainStatus'],capture_output=True,text=True,timeout=20)
    d=dict(line.split('=',1) for line in cp.stdout.splitlines() if '=' in line)
    need(cp.returncode==0 or (d.get('LoadState')=='not-found' and d.get('ActiveState')=='inactive'),'Cannot query bridge unit')
    need(d.get('ActiveState') in LIVE|{'inactive','failed'},'Unknown bridge state')
    return d
def group_name(s):need(isinstance(s,str) and GROUP_RE.fullmatch(s),'Invalid group');return s

def record(root,phase,**kw):
    path=root/'progress.json';old=parse(read(path)) if path.exists() else {'version':VERSION,'started_utc':now()}
    old.update(phase=phase,updated_utc=now(),**kw);atomic(path,old)
    print('PHASE='+phase,flush=True)

def fail(root,exc):
    atomic(root/'failure.json',{'error':type(exc).__name__+': '+str(exc),'traceback':traceback.format_exc(),'utc':now(),'automatic_generation_retry':False})
    record(root,'BLOCKED',error=str(exc))

def collect_files(root,prefix=''):
    out={}
    for p in sorted(root.rglob('*')):
        checked(p)
        if p.is_dir():continue
        need(p.is_file(),'Nonregular artifact')
        n=prefix+p.relative_to(root).as_posix();rel(n);out[n]=p
    return out

def file_archive(path,entries):
    # Only caller-selected evidence, never .transport or private SSH keys.
    need(not any('.transport' in Path(n).parts or n.endswith('id_ed25519') for n in entries),'Private key in archive selection')
    path.parent.mkdir(parents=True,exist_ok=True)
    return C.archive_paths(path,entries)

def unpack_verified(path,dest,pin,size,max_bytes=2*1024**3):
    info=P.verify_archive(path,pin,size)
    members={};total=0
    with tarfile.open(path,'r:gz') as tf:
        for t in tf:
            n=rel(t.name);need(t.isfile() and not t.islnk() and n not in members,'Bad archive member')
            total+=t.size;need(total<=max_bytes and 0<=t.size<=256*1024**2,'Archive size bound')
            members[n]=t.size
    # Never use tar.extract; every path is validated by checked()/rel().
    with tarfile.open(path,'r:gz') as tf:
        for t in tf:
            n=rel(t.name);f=tf.extractfile(t);need(f is not None,'Archive payload missing')
            b=f.read(t.size+1);need(len(b)==t.size,'Archive short read')
            once(dest/n,b)
    return info

def validate_plan(plan):
    need(plan.get('schema')==VERSION and plan.get('source_runner_sha256')==C_SHA,'Wrong handoff plan')
    gs=plan.get('gpu_groups');need(isinstance(gs,list) and gs,'No untouched groups')
    start=plan['boundary_index'];need(type(start) is int and 10<=start<180,'Boundary must begin a whole untouched group')
    ids=[]
    for offset,g in enumerate(gs,start):
        need(g['batch']==f'group-{offset:03d}' and g['order_start']==offset*5,'Noncontiguous suffix')
        rs=g['rows'];need(len(rs)==5,'Never split a five-arm group')
        need(len({(r['task'],r['size'],r['form']) for r in rs})==1 and {r['condition'] for r in rs}==set(P.ARMS),'Invalid five-arm block')
        for r in rs:need(P.identity(r['id'])=={k:r[k] for k in P.identity(r['id'])},'Invalid slot identity')
        ids.extend(r['id'] for r in rs)
    need(len(gs)==180-start and len(set(ids))==len(ids)==900-5*start,'Assignment coverage differs')
    need(plan['gpu_slots']==len(ids) and plan['cpu_prefix_slots']==5*start,'Assignment count differs')
    return gs

def reserve_suffix(plan,root,owner):
    """mkdir is the same atomic exclusion used by the old running worker.

    A marker never goes into an existing batch. The boundary prevents the old
    runner from starting even if it raced between exists() and mkdir().
    """
    for g in plan:
        if g['order_start']<50:continue
        path=root/'batches'/group_name(g['batch']);checked(path)
        if path.exists():
            need(path.is_dir(),'Batch path is not a directory');continue
        # Require an existing, contiguous prefix; a hole is not a safe boundary.
        before=[x for x in plan if x['order_start']<g['order_start']]
        need(all((root/'batches'/x['batch']).is_dir() for x in before),'Noncontiguous CPU execution history')
        need(not any((root/'batches'/x['batch']).exists() for x in plan if x['order_start']>g['order_start']),
             'A later CPU group already exists; do not split ownership')
        try:path.mkdir()
        except FileExistsError:continue # CPU won: let that entire group stay CPU.
        marker={'schema':VERSION,'owner':owner,'batch':g['batch'],'reason':'GPU_HANDOFF_BOUNDARY_RESERVATION',
                'old_worker_expected_stop':'Existing partial batch; do not duplicate numerical attempts',
                'candidate_generation_performed':False,'utc':now()}
        jw(path/'GPU_HANDOFF_RESERVATION.json',marker)
        return g,marker
    raise Blocked('No untouched whole group remains')

def cpu_init_key():
    P.host_basic();CH.mkdir(exist_ok=True,mode=0o700)
    with lock(LOCK):
        d=CH/'.transport';d.mkdir(exist_ok=True,mode=0o700)
        key=d/'id_ed25519';pub=key.with_suffix('.pub')
        if not key.exists():
            need(not pub.exists(),'Orphan public key')
            subprocess.run(['ssh-keygen','-q','-t','ed25519','-N','','-C','cpucond-a40-handoff-v1','-f',str(key)],
                           check=True,stdin=subprocess.DEVNULL,stdout=subprocess.DEVNULL,timeout=20)
        need(stat.S_IMODE(key.stat().st_mode)&0o077==0,'Dedicated key permissions are too broad')
        print(json.dumps({'public_key':read(pub).decode().strip(),'key_scope':'forced gateway on this Runpod only'}))

def fingerprint(line):
    fields=line.split();need(len(fields)>=3 and fields[1]=='ssh-ed25519','Expected Ed25519 host key')
    return 'SHA256:'+base64.b64encode(hashlib.sha256(base64.b64decode(fields[2],validate=True)).digest()).decode().rstrip('=')

def cpu_set_hostkey():
    P.host_basic();line=sys.stdin.buffer.read(4096).decode().strip()
    need(fingerprint(line)==A.HOST_FINGERPRINT,'Pinned Runpod host fingerprint mismatch')
    fields=line.split();fixed=f'[192.0.2.1]:22065 ssh-ed25519 {fields[2]}\n'
    once(CH/'.transport/known_hosts',fixed.encode());print('GPU_HOST_KEY_PINNED')

def gpu_check():
    A.remote_guard()
    need(hfile(PREP/'control/runner.py')==A_SHA,'Successful A40 setup runner differs')
    rec=parse(read(PREP/'receipt.json'));rep=parse(read(PREP/'report.json'))
    need(hfile(PREP/'report.json')==rec['report_sha256'],'A40 report changed')
    for n,h in rec['files'].items():need(hfile(PREP/rel(n))==h,'A40 setup artifact changed: '+n)
    need(rep['full_offload'] is True and rep['offloaded_layers']==rep['total_layers']==49,'A40 full offload was not verified')
    need(rep['model_sha256']==A.MODEL_SHA and rep['runtime_binary_sha256']==A.CACHED_BINARY_SHA,'Wrong GPU model/runtime')
    need(rep['native_context']==P.CTX and rep['parallel_slots']==1 and rep['model_process_stopped'] is True,'GPU setup contract differs')
    need(rep['gpu']['uuid']==GPU_UUID,'Wrong allocated GPU')
    need(not A.worker_alive(parse(read(PREP/'launch.json'))),'A40 preparation still running')
    assets=A.cached_assets() # full pinned model, runtime and library verification
    gpu=A.gpu_info();need(gpu['uuid']==GPU_UUID and gpu['free_mib']>=35000,'A40 is not available; no foreign process stopped')
    need(shutil.disk_usage(GP).free>=3*P.GIB,'GPU disk below 3GiB reserve')
    return rep,assets

def auth_line(public_key):
    fields=public_key.strip().split()
    need(len(fields) in (2,3) and fields[0]=='ssh-ed25519','Invalid dedicated public key')
    try:b=base64.b64decode(fields[1],validate=True)
    except ValueError as exc:raise Blocked('Malformed public key') from exc
    need(len(b)==51,'Invalid ed25519 public blob')
    gate=f'/usr/bin/python3 -I -S -B {GP}/control/runner.py --_gateway'
    return f'restrict,command="{gate}" ssh-ed25519 {fields[1]} cpucond-a40-handoff-v1\n'

def gpu_authorize():
    A.remote_guard();public=sys.stdin.buffer.read(4096).decode().strip();line=auth_line(public)
    auth=checked(Path('/root/.ssh/authorized_keys'));auth.parent.mkdir(mode=0o700,exist_ok=True)
    current=read(auth) if auth.exists() else b''
    matches=[x for x in current.decode().splitlines() if x.endswith(' cpucond-a40-handoff-v1')]
    need(not matches or matches==[line.strip()],'A different bridge key is already authorized')
    if not matches:
        backup=GP/'control/authorized_keys.before-bridge'
        # Private to Pod; never returned by the forced gateway or archived.
        once(backup,current)
        with auth.open('ab') as f:f.write(b'\n'+line.encode());f.flush();os.fsync(f.fileno())
    auth.chmod(0o600);once(GP/'control/bridge-public-key.txt',(public+'\n').encode())
    print('FORCED_COMMAND_BRIDGE_KEY_INSTALLED')

def bridge_args(verb,*args):
    allowed={'probe','install','start','status','send','ack','stop'};need(verb in allowed,'Gateway verb forbidden')
    return ['ssh','-F','/dev/null','-T','-p','22065','-i',str(CH/'.transport/id_ed25519'),
        '-o','BatchMode=yes','-o','IdentitiesOnly=yes','-o','PreferredAuthentications=publickey',
        '-o','PasswordAuthentication=no','-o','KbdInteractiveAuthentication=no','-o','ForwardAgent=no',
        '-o','StrictHostKeyChecking=yes','-o','HostKeyAlgorithms=ssh-ed25519',
        '-o','UserKnownHostsFile='+str(CH/'.transport/known_hosts'),'-o','GlobalKnownHostsFile=/dev/null',
        '-o','ControlMaster=no','-o','ControlPath=none','-o','ConnectTimeout=30',
        '-o','ServerAliveInterval=15','-o','ServerAliveCountMax=4',A.SERVER,shlex.join([verb,*map(str,args)])]

class TransportError(RuntimeError):pass

def bridge(verb,*args,data=None,timeout=600):
    p=subprocess.run(bridge_args(verb,*args),input=data,capture_output=True,timeout=timeout,env=P.controls_env())
    if p.returncode:raise TransportError('Runpod transport failed (no generation retry): '+p.stderr.decode(errors='replace')[-1500:])
    try:
        reply=parse(p.stdout)
    except (json.JSONDecodeError,UnicodeDecodeError) as exc:
        prefix=repr(p.stdout[:200])
        raise Blocked('RUNPOD_RPC_INVALID_JSON verb='+verb+' stdout_prefix='+prefix+
                      '; refusing to skip non-JSON reply bytes') from exc
    need(isinstance(reply,dict),'RUNPOD_RPC_NOT_AN_OBJECT verb='+verb)
    return reply

def cpu_prepare():
    P.host_basic()
    with lock(LOCK), C.io_lock():
        if (CH/'assignment.json').exists():
            validate_plan(parse(read(CH/'assignment.json')));print('HANDOFF_ALREADY_RESERVED; no second reservation');return
        need(not (CH/'reservation-intent.json').exists(),'Unresolved reservation retained; do not reserve another suffix')
        rep=bridge('probe',timeout=300);need(rep['ready'] is True,'GPU not ready')
        once(CH/'gpu-ready.json',canon(rep))
        need(hfile(CPU_ROOT/'control/runner.py')==C_SHA,'Running CPU source is not the exact pinned continuation')
        need(state(CPU_UNIT)['ActiveState'] in LIVE,'CPU campaign is not active; inspect before migration')
        at(CPU_ROOT,CPU_UNIT);C.verify_seed()
        cpuplan=parse(read(CPU_ROOT/'batch-plan.json'));allrows=parse(read(CPU_ROOT/'inputs/rows.json'))
        need(cpuplan==C.ordered_batches(allrows),'CPU schedule changed')
        _,c,_,_,_=P.modules();c.host_check(check_processes=False)
        need(shutil.disk_usage(CH).free>=20*P.GIB,'Need 20GiB free on Cherry, including evaluation artifacts')
        # Copy only frozen inputs; never CPU-generated candidates or live timing.
        sm=parse(read(CPU_ROOT/'seed-manifest.json'));copied={}
        for n,d in sm.items():
            if n.startswith(('inputs/','evaluation/','native-inputs/')) or n in ('input-receipt.json','native-input-receipt.json'):
                b=read(CPU_ROOT/rel(n));need(sha(b)==d['sha256'],'Frozen source differs')
                once(CH/n,b);(CH/n).chmod(0o444);copied[n]={'sha256':sha(b),'bytes':len(b)}
        once(CH/'input-copy-manifest.json',canon(copied))
        owner=uuid.uuid4().hex
        jw(CH/'reservation-intent.json',dict(owner=owner,cpu_runner_sha256=C_SHA,utc=now()))
        boundary,marker=reserve_suffix(cpuplan,CPU_ROOT,owner)
        start=boundary['order_start']//5;gs=[g for g in cpuplan if g['order_start']>=start*5]
        plan=dict(schema=VERSION,source_runner_sha256=C_SHA,boundary_index=start,
            cpu_prefix_slots=start*5,gpu_slots=900-start*5,gpu_groups=gs,reservation=marker,
            model=P.MODEL,model_sha256=A.MODEL_SHA,runtime_sha256=A.CACHED_BINARY_SHA,
            context_length=P.CTX,output_caps=P.CAPS,sampling=P.SAMPLING,
            inference_backend=GPU_STRATUM,measurement_host=P.HOST,
            no_cross_backend_output_identity_assumed=True,existing_candidates_regenerated=False,
            numeric_validator_sha256=P.POLICY_SHA,numeric_engine_sha256=P.ENGINE_SHA,
            ephemeral_gpu_storage=True,mirror_before_next_group=True,
            amendment='Backend and scheduling changed after CPU partial results; no candidate selection by outcome.',utc=now())
        validate_plan(plan);jw(CH/'assignment.json',plan)
        package=CH/'gpu-input';package.mkdir()
        entries={}
        def add(src,n):
            b=read(src);once(package/rel(n),b);entries[n]=package/n
        add(CH/'assignment.json','assignment.json')
        add(CH/'native-input-receipt.json','native-input-receipt.json')
        for g in gs:
            for r in g['rows']:
                add(CH/'inputs'/r['request'],'inputs/'+r['request'])
                add(CH/'native-inputs'/(r['id']+'.json'),'native-inputs/'+r['id']+'.json')
        ar=file_archive(CH/'gpu-input.tar.gz',entries);jw(CH/'gpu-input-receipt.json',ar)
        boot=file_archive(CH/'handoff-bootstrap.tar.gz',{
            'assignment.json':CH/'assignment.json','gpu-ready.json':CH/'gpu-ready.json',
            'input-copy-manifest.json':CH/'input-copy-manifest.json','gpu-input.tar.gz':CH/'gpu-input.tar.gz',
            'gpu-input-receipt.json':CH/'gpu-input-receipt.json','control/runner.py':CH/'control/runner.py'})
        jw(CH/'bootstrap-receipt.json',dict(label='bootstrap',archive=boot))
        print(json.dumps({'handoff':'RESERVED','cpu_boundary':boundary['batch'],
            'cpu_prefix_slots':start*5,'gpu_slots':plan['gpu_slots'],'gpu_groups':len(gs),
            'current_CPU_group_not_killed':True,'gpu_generation_not_yet_started':True},indent=2))

def gpu_assignment():
    plan=parse(read(GP/'input/assignment.json'));validate_plan(plan)
    tab=parse(read(GP/'input-receipt.json'))
    need(hfile(GP/'input.tar.gz')==tab['sha256'],'GPU input archive changed')
    for n,h in C.seal_table(read(GP/'input/SHA256SUMS')).items():need(hfile(GP/'input'/rel(n))==h,'GPU input changed: '+n)
    return plan

def gpu_install(pin,size):
    need(P.HEX.fullmatch(pin) and 0<size<=MAX_TRANSFER,'Invalid input transfer envelope')
    path=GP/'input.tar.gz';data=sys.stdin.buffer.read(size+1)
    need(len(data)==size and sha(data)==pin,'Input transfer truncated/corrupt')
    once(path,data);unpack_verified(path,GP/'input',pin,size)
    once(GP/'input-receipt.json',canon({'sha256':pin,'bytes':size}))
    plan=gpu_assignment()
    # The frozen native inputs are reused, then checked against the actual GPU tokenizer.
    for n,p in collect_files(GP/'input').items():
        if n.startswith(('inputs/','native-inputs/')) or n=='native-input-receipt.json':once(GP/n,read(p))
    return {'installed':True,'gpu_slots':plan['gpu_slots'],'assignment_sha256':hfile(GP/'input/assignment.json')}

def gpu_start():
    with lock(GP/'control/launch.lock'):
        if (GP/'start.json').exists():return gpu_status()
        plan=gpu_assignment();need(not (GP/'failure.json').exists(),'GPU failure retained')
        jw(GP/'start-intent.json',{'utc':now(),'assignment_sha256':hfile(GP/'input/assignment.json')})
        with (GP/'worker.log').open('xb') as log:
            proc=subprocess.Popen(['/usr/bin/python3','-I','-S','-B','-u',str(GP/'control/runner.py'),'--_gpu_worker'],
                stdin=subprocess.DEVNULL,stdout=log,stderr=subprocess.STDOUT,cwd=GP,start_new_session=True,env=P.controls_env())
        jw(GP/'start.json',dict(pid=proc.pid,process_start=A.process_start(proc.pid),utc=now(),slots=plan['gpu_slots']))
    return {'started':True,'pid':proc.pid,'gpu_slots':plan['gpu_slots']}

def gpu_status():
    d={'state':'PREPARED','receipts':[]}
    for n in ('progress','failure','complete'):
        if (GP/(n+'.json')).exists():d[n]=parse(read(GP/(n+'.json')))
    if (GP/'complete.json').exists():d['state']='COMPLETE'
    elif d.get('failure'):d['state']='BLOCKED'
    elif (GP/'start.json').exists():d['state']='RUNNING' if A.worker_alive(parse(read(GP/'start.json'))) else 'STOPPED'
    for p in sorted((GP/'receipts').glob('group-*.json')):d['receipts'].append(parse(read(p)))
    return d

def gateway():
    # The forced-command transport carries one JSON document (or raw archive).
    # Helpers such as A.gpu_info -> A.cmd also print human-readable diagnostics.
    # Keep those on stderr; never guess a JSON boundary or discard reply bytes.
    reply_stdout=sys.stdout
    with contextlib.redirect_stdout(sys.stderr):
        A.remote_guard();parts=shlex.split(os.environ.get('SSH_ORIGINAL_COMMAND',''))
        need(parts,'Missing forced gateway command');op=parts[0]
        if op=='probe' and len(parts)==1:
            rep,_=gpu_check();d={'ready':True,'report':rep,'script_sha256':hfile(__file__)}
        elif op=='install' and len(parts)==3:d=gpu_install(parts[1],int(parts[2]))
        elif op=='start' and len(parts)==1:
            need(not (GP/'start-intent.json').exists() or (GP/'start.json').exists(),'Ambiguous GPU launch; do not repeat')
            d=gpu_start()
        elif op=='status' and len(parts)==1:d=gpu_status()
        elif op=='stop' and len(parts)==1:
            if (GP/'start.json').exists():
                r=parse(read(GP/'start.json'))
                if A.worker_alive(r):os.kill(r['pid'],signal.SIGTERM)
            d={'stop_requested':True,'automatic_restart':False,'pod_not_terminated':True}
        elif op in ('send','ack') and len(parts)==(2 if op=='send' else 3):
            name=group_name(parts[1]);rr=parse(read(GP/'receipts'/(name+'.json')));ar=rr['archive']
            path=GP/'archives'/(name+'.tar.gz');need(ar['path']==str(path) and hfile(path)==ar['sha256'],'GPU archive differs')
            if op=='send':
                with P.regular(path) as f:shutil.copyfileobj(f,reply_stdout.buffer,1024**2)
                return
            need(parts[2]==ar['sha256'],'ACK digest differs');once(GP/'acks'/(name+'.json'),canon({'sha256':parts[2],'off_pod':'Cherry verified archive'}));d={'ack':name}
        else:raise Blocked('Command outside forced gateway allowlist')
    print(json.dumps(d,separators=(',',':')),file=reply_stdout,flush=True)
class GPUModel:
    def __init__(self,assets,report):
        self.assets,self.report,self.proc,self.count=assets,report,None,0
    def start(self):
        if self.proc is not None:
            need(self.proc.poll() is None,'GPU inference process died');return
        binary,model,cudaenv,*_=self.assets
        d=GP/'sessions'/f'session-{self.count:04d}';self.count+=1;d.mkdir(parents=True)
        home=GP/'infer-home';home.mkdir(exist_ok=True,mode=0o755);GP.chmod(0o755)
        A.ROOT=d;A.PORT=GPU_PORT
        gpu=A.gpu_info();need(gpu['uuid']==GPU_UUID and gpu['free_mib']>=30000,'GPU memory unavailable')
        args=A.server_argv(binary,model);env=A.env();env.update(cudaenv)
        env.update(HOME=str(home),CUDA_VISIBLE_DEVICES=GPU_UUID,OMP_NUM_THREADS='4',TMPDIR='/tmp',CUDA_CACHE_DISABLE='1')
        with socket.socket() as s:s.bind(('127.0.0.1',GPU_PORT))
        jw(d/'command.json',{'argv':args,'generation_backend':GPU_STRATUM})
        with (d/'llama-server.log').open('xb') as f:
            self.proc=subprocess.Popen(args,stdin=subprocess.DEVNULL,stdout=f,stderr=subprocess.STDOUT,
                env=env,cwd=GP,start_new_session=True)
        deadline=time.monotonic()+1200
        while True:
            need(self.proc.poll() is None,'GPU model exited during load')
            try:
                if A.api('/health',timeout=5).get('status')=='ok':break
            except (OSError,A.Blocked,http.client.HTTPException):pass
            need(time.monotonic()<deadline,'GPU model load timeout');time.sleep(2)
        props=A.api('/props');jw(d/'native-props.json',props)
        need(props.get('total_slots')==1 and props['default_generation_settings']['n_ctx']==P.CTX,'GPU context/slot changed')
        need(Path(props['model_path']).resolve()==model.resolve(),'Wrong GPU model loaded')
        need(sha(props['chat_template'].encode())==self.report['prompt_template_sha256'],'GPU chat template differs')
        off=A.wait_for_offload(d/'llama-server.log',self.proc)
        need(off['offloaded_layers']==off['total_layers']==49,'GPU offload differs')
        after=A.gpu_info();need(gpu['free_mib']-after['free_mib']>7000,'No GPU memory increase')
        jw(d/'offload.json',dict(off,gpu=after,utc=now()))
        record(GP,'GPU_MODEL_READY',gpu_model_pid=self.proc.pid,offloaded_layers=49)
    def stop(self):
        if self.proc is not None:A.stop_process(self.proc);self.proc=None
    def verify_native(self,row,nd):
        qraw=read(GP/'inputs'/row['request']);need(sha(qraw)==row['request_sha256'],'Frozen role prompt changed')
        q=parse(qraw);rendered=A.api('/apply-template',{'messages':q['messages']})['prompt']
        need(rendered==nd['prompt'],'CPU/GPU native rendered prompt mismatch')
        tokens=A.api('/tokenize',{'content':rendered,'add_special':True,'parse_special':True})['tokens']
        need(tokens==nd['tokens'],'CPU/GPU native token IDs differ')

def gpu_stream(name,cid):
    A.remote_guard();at(GP);P.PORT=GPU_PORT
    plan=gpu_assignment();g=next((x for x in plan['gpu_groups'] if x['batch']==group_name(name)),None)
    need(g is not None,'Group not assigned to GPU');r=next((x for x in g['rows'] if x['id']==cid),None)
    need(r is not None,'Slot not assigned to GPU')
    nd=C.read_native(r);d=GP/'batches'/name/'generation'/cid
    body=parse(read(d/'request.json'));need(body==P.completion_body(nd['tokens'],r['form']),'Request changed')
    P.stream_once(body,d/'response.sse')

def gpu_invoke(row,dest,batch,wall=21600):
    argv=['/usr/bin/python3','-I','-S','-B','-u',str(GP/'control/runner.py'),'--_gpu_stream',batch,row['id']]
    begin=time.monotonic()
    with (dest/'stream-worker.log').open('xb') as log:
        try:p=subprocess.run(argv,stdin=subprocess.DEVNULL,stdout=log,stderr=subprocess.STDOUT,env=P.controls_env(),timeout=wall)
        except subprocess.TimeoutExpired:
            jw(dest/'failure.json',{'reason':'generation_wall_timeout_21600s','elapsed_seconds':time.monotonic()-begin,'retry':False,'utc':now()})
            raise C.RequestFailure('generation_wall_timeout_21600s')
    if p.returncode:
        text=read(dest/'stream-worker.log',2*1024**2)
        reason='generation_wall_timeout_21600s' if b'Per-request wall limit reached' in text else 'generation_transport_or_stream_failure'
        jw(dest/'failure.json',{'reason':reason,'returncode':p.returncode,'retry':False,'utc':now()})
        raise C.RequestFailure(reason)
    return P.parse_sse(read(dest/'response.sse',P.MAX_STREAM).splitlines())

def gpu_worker():
    A.remote_guard();at(GP);P.PORT=GPU_PORT
    need(not (GP/'progress.json').exists(),'GPU worker already ran; no blind restart')
    model=None
    try:
        plan=gpu_assignment();report,assets=gpu_check();model=GPUModel(assets,report)
        once(GP/'backend-stratum.json',canon({'backend':GPU_STRATUM,'source_report':report,'same_output_as_CPU_assumed':False}))
        model.start();allrows=[r for g in plan['gpu_groups'] for r in g['rows']]
        record(GP,'NATIVE_TOKEN_AUDIT',gpu_planned=len(allrows),gpu_terminal=0)
        for i,r in enumerate(allrows,1):
            nd=C.read_native(r);model.verify_native(r,nd)
            if i%50==0:record(GP,'NATIVE_TOKEN_AUDIT',audited=i)
        jw(GP/'native-audit.json',{'count':len(allrows),'native_token_ids_byte_equal_to_CPU':True,'utc':now()})
        seen=0;transports=0
        for g in plan['gpu_groups']:
            name=g['batch'];d=GP/'batches'/name;need(not d.exists(),'Existing attempted GPU group; no retry')
            d.mkdir(parents=True);jw(d/'plan.json',g);jw(d/'backend.json',{'backend':GPU_STRATUM,'assignment_sha256':hfile(GP/'input/assignment.json')})
            rs=[]
            for r in g['rows']:
                need(shutil.disk_usage(GP).free>=2*P.GIB,'GPU disk reserve low')
                record(GP,'GENERATING_GPU_GROUP',current_batch=name,current_id=r['id'],gpu_terminal=seen,gpu_planned=len(allrows))
                rr=C.generate_slot(r,d,model,invoke=gpu_invoke);rs.append(rr);seen+=1
                transports=transports+1 if 'generation_transport_or_stream_failure' in rr['generation_errors'] else 0
                need(transports<3,'Repeated transport failures; inference infrastructure stopped')
                record(GP,'GPU_SLOT_TERMINAL',gpu_terminal=seen,last_generation_errors=rr['generation_errors'],last_status=rr['generation_status'])
            C.verify_batch_generation(rs,d)
            ar=file_archive(GP/'archives'/(name+'.tar.gz'),collect_files(d))
            rr={'batch':name,'ids':[r['id'] for r in rs],'archive':ar,'generation_backend':GPU_STRATUM,'utc':now()}
            jw(GP/'receipts'/(name+'.json'),rr)
            record(GP,'WAITING_FOR_CHERRY_CHECKPOINT',current_batch=name,gpu_terminal=seen)
            start=time.monotonic()
            while not (GP/'acks'/(name+'.json')).exists():
                need(time.monotonic()-start<12*3600,'No off-Pod ACK for 12 hours; stop before generating another group')
                time.sleep(5)
            need(parse(read(GP/'acks'/(name+'.json')))['sha256']==ar['sha256'],'Checkpoint ACK mismatch')
        model.stop();model=None
        jw(GP/'complete.json',{'gpu_slots':seen,'benchmark_generation_calls':sum(1 for p in (GP/'batches').glob('group-*/generation/*/intent.json')),'all_assigned_groups_mirrored':True,'whole_900_evaluated':False,'utc':now()})
        record(GP,'GPU_GENERATION_COMPLETE',gpu_terminal=seen)
    except BaseException as exc:fail(GP,exc);raise
    finally:
        if model is not None:model.stop()

def verify_cherry_inputs():
    for n,d in parse(read(CH/'input-copy-manifest.json')).items():
        b=read(CH/rel(n));need(len(b)==d['bytes'] and sha(b)==d['sha256'],'Cherry immutable input changed')
    plan=parse(read(CH/'assignment.json'));validate_plan(plan)
    marker=CPU_ROOT/'batches'/f'group-{plan["boundary_index"]:03d}'/'GPU_HANDOFF_RESERVATION.json'
    need(parse(read(marker))==plan['reservation'],'CPU handoff reservation changed')
    return plan

def mirror_group(rec):
    name=group_name(rec['batch']);ar=rec['archive']
    need(ar['path']==str(GP/'archives'/(name+'.tar.gz')) and P.HEX.fullmatch(ar['sha256']),'GPU archive path/pin invalid')
    need(type(ar['bytes']) is int and 0<ar['bytes']<=MAX_TRANSFER,'GPU group archive too large')
    plan=parse(read(CH/'assignment.json'));g=next(x for x in plan['gpu_groups'] if x['batch']==name)
    need(rec['ids']==[r['id'] for r in g['rows']],'GPU receipt group membership differs')
    path=CH/'incoming-archives'/(name+'.tar.gz');path.parent.mkdir(exist_ok=True)
    rp=CH/'incoming-receipts'/(name+'.json')
    if rp.exists():
        saved=parse(read(rp));need(saved['gpu_receipt']==rec and hfile(path)==ar['sha256'],'Mirrored receipt conflict');return
    with C.io_lock():
        if not path.exists():
            part=path.with_name(path.name+'.partial-'+uuid.uuid4().hex)
            with part.open('xb') as f:
                p=subprocess.run(bridge_args('send',name),stdout=f,stderr=subprocess.PIPE,timeout=1800,env=P.controls_env())
                f.flush();os.fsync(f.fileno())
            if p.returncode:raise TransportError('GPU checkpoint transport failed; partial retained')
            P.verify_archive(part,ar['sha256'],ar['bytes']);os.rename(part,path)
        dest=CH/'incoming'/name;unpack_verified(path,dest,ar['sha256'],ar['bytes'])
        need(parse(read(dest/'plan.json'))==g,'GPU archived plan differs')
        need(parse(read(dest/'backend.json'))['backend']==GPU_STRATUM,'Missing CUDA stratum')
        for r in g['rows']:
            rr=parse(read(dest/'generation-records'/(r['id']+'.json')))
            if rr['source_path']:
                b=read(dest/'candidate-sources'/Path(rr['source_path']).name)
                once(CH/'evaluation'/rel(rr['source_path']),b);(CH/'evaluation'/rr['source_path']).chmod(0o444)
        oldroot=C.ROOT;at(CH)
        rs=[parse(read(dest/'generation-records'/(r['id']+'.json'))) for r in g['rows']]
        C.verify_batch_generation(rs,dest)
        jw(rp,{'gpu_receipt':rec,'local_archive_sha256':ar['sha256'],'local_archive_path':str(path),
               'all_payload_hashes_verified':True,'classification_replay_verified':True,'utc':now()})
        sync_dir(path.parent);sync_dir(rp.parent)
    print('CHERRY_GPU_CHECKPOINT_VERIFIED '+name,flush=True)

def eval_command():
    return ['systemd-run','--unit='+EVAL_UNIT,'--property=Type=exec','--property=Restart=no',
        '--property=MemoryMax=24G','--property=MemorySwapMax=0','--property=TasksMax=256',
        '--property=PrivateNetwork=yes','--property=RuntimeMaxSec=infinity','--property=KillMode=control-group',
        '--property=TimeoutStopSec=90','--property=UMask=0077','--property=LimitCORE=0',
        '--property=StandardOutput=append:'+str(CH/'evaluation.log'),'--property=StandardError=append:'+str(CH/'evaluation.log'),
        '--setenv=CPUCOND_BATCH_UNIT='+EVAL_UNIT,'--working-directory=/root','--',
        '/usr/bin/python3','-I','-S','-B','-u',str(CH/'control/runner.py'),'--_evaluate']

def check_cpu_prefix():
    plan=parse(read(CH/'assignment.json'));b=plan['boundary_index']
    need(state(CPU_UNIT)['ActiveState'] not in LIVE,'Waiting for CPU group boundary')
    # All CPU-owned groups must have completed, not merely stopped midway.
    for i in range(9,b):
        rec=parse(read(CPU_ROOT/'batch-receipts'/f'group-{i:03d}.json'))
        need(rec['batch']==f'group-{i:03d}','CPU receipt name differs')
        base=CPU_ROOT/'batches'/rec['batch']
        need(hfile(base/'performance/outcomes.jsonl')==rec['outcomes_sha256'],'CPU outcomes changed')
        need(hfile(base/'validation/result-index.json')==rec['validation_sha256'],'CPU validation changed')
    for g in plan['gpu_groups']:
        path=CPU_ROOT/'batches'/g['batch']
        if g['batch']==f'group-{b:03d}':
            need({p.name for p in path.iterdir()}=={'GPU_HANDOFF_RESERVATION.json'},'CPU entered reserved group unexpectedly')
        else:need(not path.exists(),'CPU generated in GPU-owned suffix')
    return plan

def maybe_start_evaluator():
    if (CH/'evaluation-start.json').exists():return
    if state(CPU_UNIT)['ActiveState'] in LIVE:return
    check_cpu_prefix()
    with lock(CH/'evaluation-launch.lock'):
        if (CH/'evaluation-start.json').exists():return
        need(state(EVAL_UNIT)['ActiveState'] not in LIVE,'Unexpected evaluator unit')
        at(CH,EVAL_UNIT)
        with P.locks():
            _,c,e,_,_=P.modules();C.no_foreign_jobs();c.host_check(check_processes=False);e.no_other_jobs()
            argv=eval_command();jw(CH/'evaluation-start.json',{'argv':argv,'utc':now(),'runner_sha256':hfile(__file__)})
        p=subprocess.run(argv,capture_output=True,text=True,env=P.controls_env(),timeout=60)
        jw(CH/'evaluation-submission.json',{'returncode':p.returncode,'stdout':p.stdout,'stderr':p.stderr})
        need(p.returncode==0,'Evaluation launch unconfirmed; inspect, do not launch twice')
        print('CHERRY_GPU_CANDIDATE_EVALUATION_STARTED',flush=True)

def bridge_worker():
    P.host_basic();plan=verify_cherry_inputs()
    try:
        ar=parse(read(CH/'gpu-input-receipt.json'))
        with C.io_lock():reply=bridge('install',ar['sha256'],ar['bytes'],data=read(CH/'gpu-input.tar.gz',MAX_TRANSFER),timeout=1200)
        need(reply['assignment_sha256']==hfile(CH/'assignment.json'),'Runpod installed wrong assignment')
        bridge('start',timeout=60)
        mirrored=set();errors=0
        while True:
            try:doc=bridge('status',timeout=60);errors=0
            except (TransportError,OSError,subprocess.SubprocessError) as exc:
                errors+=1;record(CH,'GPU_CONNECTION_PENDING',transport_errors=errors,last_error=str(exc))
                need(errors<=120,'Repeated GPU connection failure; worker did not reissue any generation')
                time.sleep(30);continue
            atomic(CH/'gpu-observation.json',doc)
            pending=False
            for rec in doc['receipts']:
                name=rec['batch']
                if name not in mirrored:
                    try:
                        mirror_group(rec);bridge('ack',name,rec['archive']['sha256']);mirrored.add(name)
                    except (TransportError,OSError,subprocess.SubprocessError) as exc:
                        record(CH,'CHECKPOINT_TRANSFER_PENDING',last_error=str(exc),current_batch=name)
                        pending=True;time.sleep(15);break
            if pending:continue
            maybe_start_evaluator()
            record(CH,'TRANSFERRING_GPU_GROUPS',mirrored_groups=len(mirrored),gpu_state=doc['state'],gpu_progress=doc.get('progress'),
                   cpu_boundary_waiting=state(CPU_UNIT)['ActiveState'] in LIVE)
            if doc['state']=='COMPLETE':
                need(len(mirrored)==len(plan['gpu_groups']),'GPU complete but mirror incomplete')
                once(CH/'delivery-complete.json',canon({'groups':len(mirrored),'slots':plan['gpu_slots'],'gpu_complete':doc['complete'],'utc':now()}))
                # CPU may still be finishing its last group; do not kill it.
                while not (CH/'evaluation-start.json').exists():maybe_start_evaluator();time.sleep(15)
                record(CH,'GPU_DELIVERY_COMPLETE');return
            need(doc['state']=='RUNNING','GPU worker stopped; all available completed groups preserved')
            time.sleep(10)
    except BaseException as exc:fail(CH,exc);raise

def cpu_stop():
    P.host_basic()
    # Emergency stop only. Partial numerical attempts are retained, never retried.
    reply=bridge('stop',timeout=60)
    for unit in (BRIDGE_UNIT,EVAL_UNIT):
        st=state(unit)
        if st['ActiveState'] in LIVE:
            subprocess.run(['systemctl','stop',unit],check=True,timeout=120,env=P.controls_env())
    print(json.dumps({'new_handoff_jobs_stopped':True,'GPU_stop_reply':reply,'old_CPU_campaign_not_killed':True,'server_rental_unchanged':True}))

def cpu_start_bridge():
    P.host_basic()
    with lock(LOCK):
        if (CH/'bridge-start.json').exists():print('BRIDGE_ALREADY_SUBMITTED; no new GPU start');return
        verify_cherry_inputs();argv=['systemd-run','--unit='+BRIDGE_UNIT,'--property=Type=exec','--property=Restart=no',
            '--property=MemoryMax=4G','--property=TasksMax=128','--property=RuntimeMaxSec=infinity','--property=UMask=0077',
            '--property=StandardOutput=append:'+str(CH/'bridge.log'),'--property=StandardError=append:'+str(CH/'bridge.log'),
            '--working-directory=/root','--','/usr/bin/python3','-I','-S','-B','-u',str(CH/'control/runner.py'),'--_bridge']
        jw(CH/'bridge-start.json',{'argv':argv,'utc':now(),'runner_sha256':hfile(__file__)})
        p=subprocess.run(argv,capture_output=True,text=True,env=P.controls_env(),timeout=60)
        jw(CH/'bridge-submission.json',{'returncode':p.returncode,'stdout':p.stdout,'stderr':p.stderr})
        need(p.returncode==0,'Bridge launch unconfirmed; do not resubmit')
    print('A40_HANDOFF_STARTED; server-to-server transfer; WSL is only monitoring',flush=True)
def combined_results(core):
    at(CPU_ROOT,CPU_UNIT);cpu,cv=C.collect_results();at(CH,EVAL_UNIT)
    gpu=[];gv=[]
    for p in sorted((CH/'evaluation-receipts').glob('group-*.json')):
        rec=parse(read(p));d=CH/'evaluated'/rec['batch']
        need(hfile(d/'performance/outcomes.jsonl')==rec['outcomes_sha256'],'GPU evaluation changed')
        need(hfile(d/'validation/result-index.json')==rec['validation_sha256'],'GPU validation changed')
        gpu.extend(parse(x) for x in read(d/'performance/outcomes.jsonl').splitlines())
        gv.extend(parse(read(d/'validation/result-index.json')))
    rows=[dict(r,generation_backend=CPU_STRATUM) for r in cpu]+[dict(r,generation_backend=GPU_STRATUM) for r in gpu]
    need(len({r['id'] for r in rows})==len(rows),'Duplicate CPU/GPU slot ownership')
    plan=parse(read(CH/'assignment.json'))
    cpu_ids={r['id'] for r in parse(read(CH/'inputs/rows.json'))[:plan['cpu_prefix_slots']]}
    need({r['id'] for r in cpu}==cpu_ids,'CPU prefix incomplete/different')
    gpu_ids={r['id'] for g in plan['gpu_groups'] for r in g['rows']}
    need({r['id'] for r in gpu}<=gpu_ids and not cpu_ids&gpu_ids,'GPU candidate outside assignment')
    return rows,cv+gv

def final_summary(core):
    rows,vr=combined_results(core);need({r['id'] for r in rows}==P.grid(),'900 evaluation outcomes not yet present')
    plan=parse(read(CH/'assignment.json'));by={r['id']:r for r in rows}
    order=parse(read(CH/'inputs/rows.json'));rows=[by[r['id']] for r in order]
    summary={'completion':'A40_HANDOFF_900_ACCOUNTED_AND_EVALUATED','model':P.MODEL,'slots':900,
        'cpu_prefix_slots':plan['cpu_prefix_slots'],'gpu_suffix_slots':plan['gpu_slots'],
        'performance':core.metric(rows),'validation':core.validation_summary(vr),
        'by_generation_backend':{backend:core.metric([r for r in rows if r['generation_backend']==backend]) for backend in (CPU_STRATUM,GPU_STRATUM)},
        'formal_equivalence_proven':False,'no_cross_backend_identity_assumed':True,
        'all_slots_successful':all(r['measurement_valid'] for r in rows),
        'automatic_regeneration':False,'statistical_scope':'Descriptive only. CPU and CUDA strata are reported separately; no automatic causal/significance claim.',
        'utc':now()}
    jw(CH/'summary.json',summary);save(CH/'analysis/outcomes.csv',core.table_csv(rows))
    pairs=[]
    groupby={}
    for r in rows:groupby.setdefault((r['task'],r['size'],r['form']),{})[r['condition']]=r
    for (k,s,f),arms in groupby.items():
        for num,den in (('S1','P0'),('S2','P0'),('S1','W1'),('S2','W2')):
            a,b=arms[num],arms[den]
            if a['measurement_valid'] and b['measurement_valid']:
                need(a['generation_backend']==b['generation_backend'],'Cross-backend matched group forbidden')
                pairs.append(dict(task=k,size=s,form=f,contrast=num+'_over_'+den,
                    generation_backend=a['generation_backend'],speedup_ratio=a['speedup']/b['speedup']))
    save(CH/'analysis/matched_pairs_by_backend.csv',core.table_csv(pairs))
    entries={'summary.json':CH/'summary.json','assignment.json':CH/'assignment.json','gpu-ready.json':CH/'gpu-ready.json'}
    entries.update(collect_files(CH/'analysis','analysis/'))
    entries.update(collect_files(CH/'evaluation-receipts','evaluation-receipts/'))
    ar=file_archive(CH/'final-summary.tar.gz',entries)
    jw(CH/'complete.json',{'completion':summary['completion'],'archive':ar,'summary_sha256':hfile(CH/'summary.json'),'utc':now()})
    record(CH/'eval-control','COMPLETE',accounted_slots=900)

def evaluate_worker():
    at(CH,EVAL_UNIT);P.cgroup_guard(private=True);plan=verify_cherry_inputs();check_cpu_prefix()
    control=CH/'eval-control';control.mkdir(exist_ok=True)
    try:
        need(not (control/'started.json').exists(),'Evaluation already entered; no numerical retry')
        jw(control/'started.json',{'utc':now(),'runner_sha256':hfile(__file__)})
        with P.locks():
            core,c,e,f,m=P.modules();boot=Path('/proc/sys/kernel/random/boot_id').read_text().strip()
            def check():
                need(Path('/proc/sys/kernel/random/boot_id').read_text().strip()==boot,'CPU rebooted')
                c.controls();need(shutil.disk_usage(CH).free>=3*P.GIB,'CPU disk reserve low')
            check();c.host_check(check_processes=False)
            for g in plan['gpu_groups']:
                name=g['batch'];rp=CH/'incoming-receipts'/(name+'.json')
                record(control,'WAITING_FOR_SAVED_GPU_GROUP',current_batch=name)
                while not rp.exists():
                    need(not (CH/'failure.json').exists(),'Transfer coordinator failed before this group arrived')
                    time.sleep(10)
                with C.io_lock():
                    check();d=CH/'evaluated'/name;need(not d.exists(),'Partial measurement preserved; no retry')
                    d.mkdir(parents=True)
                    for n,p in collect_files(CH/'incoming'/name).items():
                        if n!='SHA256SUMS':once(d/n,read(p))
                    for r in g['rows']:
                        nd=C.read_native(r);need(nd['id']==r['id'],'Native input changed')
                    rs=[parse(read(d/'generation-records'/(r['id']+'.json'))) for r in g['rows']]
                    C.verify_batch_generation(rs,d)
                    record(control,'EVALUATING_GPU_GROUP',current_batch=name)
                    def progress(**kw):
                        phase=kw.pop('phase','EVALUATING_GPU_GROUP');record(control,phase,current_batch=name,**kw)
                    outs,vr,summary=C.evaluate_batch(core,c,e,f,m,rs,d,check,progress)
                    # Immutable numeric helper outputs remain unchanged; explicit stratum is separate.
                    jw(d/'generation-backend.json',{'stratum':GPU_STRATUM,'cuda_report_sha256':hfile(CH/'gpu-ready.json')})
                    C.verify_batch_generation(rs,d)
                    ar,seal,n=core.archive_all(d,lambda **kw:None);P.verify_archive(Path(ar['path']),ar['sha256'],ar['bytes'])
                    rr={'batch':name,'archive':ar,'ids':[r['id'] for r in rs],
                        'outcomes_sha256':hfile(d/'performance/outcomes.jsonl'),
                        'validation_sha256':hfile(d/'validation/result-index.json'),'generation_backend':GPU_STRATUM,'utc':now()}
                    jw(CH/'evaluation-receipts'/(name+'.json'),rr)
                    rows,_=combined_results(core)
                    record(control,'GROUP_EVALUATION_COMPLETE',current_batch=name,accounted_slots=len(rows),
                           valid_measurements_total=sum(r['measurement_valid'] for r in rows))
                    print('A40_GROUP_GENERATION_AND_CHERRY_EVALUATION_COMPLETE '+name,flush=True)
            with C.io_lock():final_summary(core)
    except BaseException as exc:fail(control,exc);raise

def archive_catalog():
    result=[]
    if (CH/'bootstrap-receipt.json').exists():result.append(parse(read(CH/'bootstrap-receipt.json')))
    for p in sorted((CH/'incoming-receipts').glob('group-*.json')):
        rr=parse(read(p));ar=rr['gpu_receipt']['archive']
        result.append({'label':'gpu-'+p.stem,'archive':dict(ar,path=rr['local_archive_path']),'source_receipt':rr})
    for p in sorted((CH/'evaluation-receipts').glob('group-*.json')):
        rr=parse(read(p));result.append({'label':'eval-'+p.stem,'archive':rr['archive'],'source_receipt':rr})
    if (CH/'complete.json').exists():result.append({'label':'summary','archive':parse(read(CH/'complete.json'))['archive']})
    return result

def cpu_status():
    P.host_basic();d={'state':'PREPARED','archives':archive_catalog(),
        'bridge_service':state(BRIDGE_UNIT),'evaluation_service':state(EVAL_UNIT),'original_CPU_service':state(CPU_UNIT)}
    for name in ('assignment','progress','failure','gpu-observation','delivery-complete','complete'):
        if (CH/(name+'.json')).exists():
            v=parse(read(CH/(name+'.json')))
            if name=='assignment':v={k:v[k] for k in ('boundary_index','cpu_prefix_slots','gpu_slots')}
            d[name]=v
    if (CH/'eval-control/progress.json').exists():d['evaluation_progress']=parse(read(CH/'eval-control/progress.json'))
    if (CH/'eval-control/failure.json').exists():d['evaluation_failure']=parse(read(CH/'eval-control/failure.json'))
    if 'complete' in d:d['state']='COMPLETE_900'
    elif 'failure' in d or 'evaluation_failure' in d:d['state']='BLOCKED'
    elif d['bridge_service']['ActiveState'] in LIVE or d['evaluation_service']['ActiveState'] in LIVE:d['state']='RUNNING'
    return d

def cpu_send(label):
    P.host_basic();rr=next((x for x in archive_catalog() if x['label']==label),None)
    need(rr is not None,'Unknown archive label');ar=rr['archive'];p=checked(ar['path'])
    need(p.is_relative_to(CH) and '.transport' not in p.parts,'Archive outside handoff evidence')
    with C.io_lock():
        need(hfile(p)==ar['sha256'],'Archive changed before sending')
        with P.regular(p) as f:shutil.copyfileobj(f,sys.stdout.buffer,1024**2)

def remote_install_code():
    return "import sys,os,hashlib,socket,stat,fcntl,json,subprocess,uuid,time\nfrom pathlib import Path\n\nOLD='f8a613b015d146c068e7a0cfeec202a6a8951a2bfabbb45e17ebc511eb59c4da'\nCH=Path('/srv/research/cpucond-a40-handoff-v1')\nGP=Path('/workspace/cpucond-a40-handoff-v1')\nCPU_ROOT=Path('/srv/research/cpucond-open14b-continuous-v1')\n\ndef need(ok,msg):\n    if not ok:raise RuntimeError('RPC_REPAIR_REFUSED: '+msg)\n\ndef safe(path):\n    path=Path(path).absolute()\n    need('..' not in path.parts,'path traversal')\n    need(not any(p.is_symlink() for p in (path,*path.parents)),'symlink: '+str(path))\n    return path\n\ndef read(path):\n    p=safe(path)\n    with p.open('rb') as f:\n        st=os.fstat(f.fileno())\n        need(stat.S_ISREG(st.st_mode) and st.st_size<=1024**2,'nonregular/oversized runner')\n        b=f.read(1024**2+1)\n    need(len(b)==st.st_size and len(b)<=1024**2,'runner length changed')\n    return b\n\ndef sha(b):return hashlib.sha256(b).hexdigest()\n\ndef fsync_dir(p):\n    fd=os.open(p,os.O_RDONLY|os.O_DIRECTORY)\n    try:os.fsync(fd)\n    finally:os.close(fd)\n\ndef save_once(path,b):\n    path=safe(path)\n    if path.exists():need(read(path)==b,'existing repair evidence differs: '+str(path));return\n    with path.open('xb') as f:f.write(b);f.flush();os.fsync(f.fileno())\n\ndef inactive_units():\n    for unit in ('a40-handoff-bridge-v1.service','cpucond69-a40-handoff-eval-v1.service'):\n        cp=subprocess.run(['systemctl','show',unit,'-p','LoadState','-p','ActiveState','-p','MainPID'],\n                          stdin=subprocess.DEVNULL,capture_output=True,text=True,timeout=20)\n        d=dict(x.split('=',1) for x in cp.stdout.splitlines() if '=' in x)\n        absent=d.get('LoadState')=='not-found' and d.get('ActiveState')=='inactive'\n        need(cp.returncode==0 or absent,'cannot establish service state: '+unit)\n        need(d.get('ActiveState') in ('inactive','failed') and d.get('MainPID','0')=='0',\n             'handoff service active or unknown: '+unit)\n\ndef verify_pre_assignment(root,role,cpu_root=CPU_ROOT):\n    root=safe(root)\n    allowed={'control','.transport'} if role=='cpu' else {'control'}\n    entries={p.name for p in root.iterdir()}\n    need(entries<=allowed,'handoff has state beyond pre-assignment: '+repr(sorted(entries-allowed)))\n    # No completed/partial GPU request, reservation, or numerical job may exist.\n    # Only this new handoff root is inspected; the older CPU campaign is not altered.\n    for entry in root.iterdir():safe(entry);need(entry.is_dir(),'unexpected non-directory')\n    if role=='cpu':\n        inactive_units()\n        batches=safe(cpu_root/'batches')\n        need(batches.is_dir(),'original CPU history missing')\n        for batch in batches.iterdir():\n            if not batch.name.startswith('group-'):continue\n            safe(batch)\n            need(not (batch/'GPU_HANDOFF_RESERVATION.json').exists(),'CPU suffix already reserved')\n\ndef no_active_runner(path):\n    token=os.fsencode(path)\n    for proc in Path('/proc').iterdir():\n        if not proc.name.isdigit() or int(proc.name)==os.getpid():continue\n        try:\n            words=(proc/'cmdline').read_bytes().split(b'\\0')\n        except (FileNotFoundError,ProcessLookupError):continue\n        need(token not in words,'handoff runner already executing, PID='+proc.name)\n\ndef install(path,b,pin,role,repair=False):\n    p=safe(path);need(sha(b)==pin and len(b)<=1024**2,'upload hash/size mismatch')\n    p.parent.mkdir(parents=True,exist_ok=True,mode=0o700)\n    if not p.exists():\n        need(not repair or not any(x.name!='control' for x in p.parent.parent.iterdir()),\n             'missing runner with pre-existing state')\n        save_once(p,b);fsync_dir(p.parent);print('HANDOFF_RUNNER_INSTALLED');return\n    current=read(p)\n    if current==b:print('HANDOFF_RUNNER_HASH_VERIFIED');return\n    need(repair,'existing runner differs; explicit --repair-rpc-preflight required')\n    need(sha(current)==OLD,'not the exact known V1 predecessor')\n    root=p.parent.parent\n    lkpath=Path('/run/lock/cpucond-a40-handoff-control-v1.lock') if role=='cpu' else root/'control/launch.lock'\n    fd=os.open(safe(lkpath),os.O_RDWR|os.O_CREAT|os.O_NOFOLLOW,0o600)\n    with os.fdopen(fd,'a') as lk:\n        fcntl.flock(lk,fcntl.LOCK_EX|fcntl.LOCK_NB)\n        verify_pre_assignment(root,role);no_active_runner(p)\n        need(read(p)==current,'runner changed during preflight')\n        backup=p.parent/('runner.before-rpc-json-fix-'+OLD[:12]+'.py')\n        save_once(backup,current)\n        evidence={'repair':'diagnostic_stdout_to_stderr','old_sha256':OLD,'new_sha256':pin,\n                  'role':role,'pre_assignment_only':True,'backed_up_runner':str(backup),\n                  'model_or_numerical_retries':0,'old_campaign_modified':False}\n        save_once(p.parent/('rpc-json-fix-intent-'+pin[:12]+'.json'),\n                  (json.dumps(evidence,sort_keys=True)+'\\n').encode())\n        tmp=p.with_name(p.name+'.rpc-fix-'+uuid.uuid4().hex)\n        with tmp.open('xb') as f:f.write(b);f.flush();os.fsync(f.fileno())\n        need(read(p)==current,'runner changed before replacement')\n        os.replace(tmp,p);fsync_dir(p.parent)\n        need(read(p)==b and read(backup)==current,'replacement/backup verification failed')\n        print('RPC_JSON_FIX_INSTALLED_PRE_ASSIGNMENT_ONLY role='+role)\n\nif __name__=='__main__':\n    need(len(sys.argv)==5,'installer arguments')\n    path,pin,role,mode=sys.argv[1:]\n    need(role in ('cpu','gpu') and mode in ('normal','repair'),'role/mode')\n    need(os.geteuid()==0,'remote root required')\n    host=socket.gethostname().split('.')[0]\n    need((host=='cpucond-skylake-01') if role=='cpu' else (host!='cpucond-skylake-01'),'wrong host')\n    target=(CH if role=='cpu' else GP)/'control/runner.py'\n    need(Path(path)==target,'unexpected install path')\n    os.umask(0o077)\n    data=sys.stdin.buffer.read(1024**2+1)\n    install(target,data,pin,role,mode=='repair')\n"

def remote_install(conn,root,gpu=False,repair=False):
    raw=read(__file__);pin=sha(raw)
    argv=['/usr/bin/python3','-I','-S','-B','-c',remote_install_code(),
          str(root/'control/runner.py'),pin,'gpu' if gpu else 'cpu','repair' if repair else 'normal']
    if gpu:conn.run(argv,data=raw)
    else:conn.exec(argv,input=raw)

def cpu_call(conn,op,data=None,capture=False):
    return conn.exec(['/usr/bin/python3','-I','-S','-B','-u',str(CH/'control/runner.py'),op],input=data,capture=capture)

def local_collect(conn,items):
    root=checked(Path.home()/LOCAL_REL);root.mkdir(parents=True,exist_ok=True)
    for rr in items:
        label=rr['label'];need(re.fullmatch(r'(bootstrap|summary|(gpu|eval)-group-\d{3})',label),'Invalid local label')
        ar=rr['archive'];dest=root/(label+'.tar.gz');rp=root/(label+'-server-receipt.json')
        once(rp,canon(rr))
        if not dest.exists():
            need(shutil.disk_usage(root).free>=ar['bytes']+P.GIB,'Insufficient WSL space')
            part=dest.with_name(dest.name+'.partial-'+uuid.uuid4().hex)
            cmd=['/usr/bin/python3','-I','-S','-B',str(CH/'control/runner.py'),'--_cpu_send',label]
            with part.open('xb') as f:
                subprocess.run(['ssh',*conn.opts,P.SERVER,shlex.join(cmd)],stdout=f,check=True)
                f.flush();os.fsync(f.fileno())
            P.verify_archive(part,ar['sha256'],ar['bytes']);os.rename(part,dest)
        vr=P.verify_archive(dest,ar['sha256'],ar['bytes'])
        atomic(root/(label+'-local-receipt.json'),dict(vr,utc=now(),source_receipt_sha256=sha(canon(rr))))
        print('A40_HANDOFF_LOCAL_COPY_VERIFIED '+label,flush=True)

def local(mode,allow=False,repair=False):
    need(not repair or mode=='run','RPC preflight repair is permitted only with --run')
    need(os.geteuid()!=0 and socket.gethostname().split('.')[0]!=P.HOST,'Run from WSL without sudo')
    cpu=P.SSH();gpu=None
    try:
        remote_install(cpu,CH,repair=repair)
        if mode=='stop':cpu_call(cpu,'--_cpu_stop');return
        if mode=='run':
            need(allow,'Use --allow-ephemeral-with-checkpoints to authorize GPU one-group-at-a-time scratch storage')
            A.fingerprint_check(Path.home()/'.ssh/id_ed25519');gpu=A.Connection();remote_install(gpu,GP,True,repair=repair)
            pub=parse(cpu_call(cpu,'--_cpu_key',capture=True).stdout)['public_key']
            gpu.run(['/usr/bin/python3','-I','-S','-B',str(GP/'control/runner.py'),'--_gpu_authorize'],data=pub.encode())
            keyscan=subprocess.run(['ssh-keygen','-F','[192.0.2.1]:22065','-f',str(Path.home()/'.ssh/known_hosts')],capture_output=True,text=True,check=True)
            hostline=next((l for l in keyscan.stdout.splitlines() if not l.startswith('#') and ' ssh-ed25519 ' in l and fingerprint(l)==A.HOST_FINGERPRINT),None)
            need(hostline,'Runpod pinned host key not found')
            cpu_call(cpu,'--_cpu_hostkey',data=hostline.encode())
            cpu_call(cpu,'--_cpu_prepare')
            doc=parse(cpu_call(cpu,'--_cpu_status',capture=True).stdout)
            local_collect(cpu,[i for i in doc['archives'] if i['label']=='bootstrap'])
            cpu_call(cpu,'--_cpu_start')
        done=set();last=None
        while True:
            d=parse(cpu_call(cpu,'--_cpu_status',capture=True).stdout)
            if mode=='status':print(json.dumps(d,ensure_ascii=False,indent=2));return
            g=d.get('gpu-observation',{});gp=g.get('progress',{});ep=d.get('evaluation_progress',{})
            brief={'state':d['state'],'assignment':d.get('assignment'),'GPU_phase':gp.get('phase'),
                'GPU_terminal':gp.get('gpu_terminal'),'current_GPU_id':gp.get('current_id'),
                'CPU_original_state':d['original_CPU_service'].get('ActiveState'),
                'evaluation_phase':ep.get('phase'),'evaluated_900_total':ep.get('accounted_slots'),
                'valid_measurements_total':ep.get('valid_measurements_total')}
            line=json.dumps(brief,ensure_ascii=False)
            if line!=last:print(line,flush=True);last=line
            for rr in d['archives']:
                if rr['label'] not in done:
                    try:local_collect(cpu,[rr]);done.add(rr['label'])
                    except (subprocess.SubprocessError,OSError) as exc:print('WSL_TRANSFER_PENDING '+str(exc)+'; server bridge continues',flush=True)
            if d['state']=='COMPLETE_900':
                need(len(done)==len(d['archives']),'Server complete, WSL transfer pending; use --collect')
                print('A40_HANDOFF_900_EVALUATED_AND_NEW_CHECKPOINTS_LOCAL_VERIFIED');return
            if mode=='collect':return
            need(d['state']=='RUNNING','Handoff stopped; inspect --status, do not regenerate/repeat numerical jobs')
            time.sleep(30)
    except KeyboardInterrupt:print('WSL_WATCH_DISCONNECTED; server-to-server bridge and jobs continue')
    finally:
        if gpu:gpu.close()
        cpu.close()

