def main():
    os.umask(0o077)
    parser=argparse.ArgumentParser(description=__doc__)
    group=parser.add_mutually_exclusive_group(required=True)
    for n in ('run','watch','status','collect','stop','self-test','_cpu_key','_cpu_hostkey','_cpu_prepare','_cpu_start',
              '_cpu_status','_cpu_stop','_gpu_authorize','_gateway','_gpu_worker','_bridge','_evaluate'):
        group.add_argument('--'+n,action='store_true')
    group.add_argument('--_gpu_stream',nargs=2);group.add_argument('--_cpu_send')
    parser.add_argument('--allow-ephemeral-with-checkpoints',action='store_true')
    parser.add_argument('--repair-rpc-preflight',action='store_true',help='Replace only the known V1 runner before any handoff reservation or work; keep old source backup')
    a=parser.parse_args()
    if a.self_test:self_test();return
    if a._cpu_key:cpu_init_key();return
    if a._cpu_hostkey:cpu_set_hostkey();return
    if a._gpu_authorize:gpu_authorize();return
    if a._cpu_prepare:cpu_prepare();return
    if a._cpu_start:cpu_start_bridge();return
    if a._cpu_status:print(json.dumps(cpu_status(),ensure_ascii=False));return
    if a._cpu_stop:cpu_stop();return
    if a._cpu_send:cpu_send(a._cpu_send);return
    if a._gateway:gateway();return
    if a._gpu_stream:gpu_stream(*a._gpu_stream);return
    if a._gpu_worker or a._bridge or a._evaluate:
        def terminate(sig,frame):raise Blocked('Interrupted; partial evidence retained; no automatic retry')
        signal.signal(signal.SIGTERM,terminate)
        if a._gpu_worker:gpu_worker()
        elif a._bridge:bridge_worker()
        else:evaluate_worker()
        return
    mode=next(n for n in ('run','watch','status','collect','stop') if getattr(a,n))
    local(mode,a.allow_ephemeral_with_checkpoints,a.repair_rpc_preflight)

if __name__=='__main__':
    try:main()
    except KeyboardInterrupt:raise SystemExit(130)
    except Exception as exc:
        print('A40_HANDOFF_BLOCKED: '+type(exc).__name__+': '+str(exc),file=sys.stderr,flush=True)
        print('Existing model/candidates/timings preserved; no automatic generation or numeric retry.',file=sys.stderr,flush=True)
        raise SystemExit(2)
